<p class="eyebrow">Wallet</p><h1>Deposit funds</h1><p>Use a method available to your investment region. Deposits are reviewed manually before your wallet is credited.</p><div class="metric-grid"><article class="metric-card"><span>Available cash</span><strong><?= money((int)$wallet['available_balance_minor']) ?></strong></article></div><div class="card-grid"><?php foreach($methods as $item): ?><a class="card" href="<?= e(route('dashboard.deposit')) ?>?method=<?= e($item['id']) ?>"><h2><?= e($item['name']) ?></h2><p><?= e($item['description']??'Manual deposit') ?></p><small><?= e($item['estimated_processing_time']??'Review time shown after submission') ?></small></a><?php endforeach; ?></div><?php if($method): ?><section class="card"><h2><?= e($method['name']) ?></h2><p><?= nl2br(e($method['instructions']??'')) ?></p><form method="post" action="<?= e(route('dashboard.deposit.submit')) ?>" class="form-stack" enctype="multipart/form-data"><?= app('csrf')->input() ?><input type="hidden" name="method_id" value="<?= e($method['id']) ?>"><label class="field"><span>Amount (<?= e(country()->currencyCode()) ?>)</span><input name="amount" inputmode="decimal" required></label><?php require __DIR__.'/../components/dynamic-form.php'; ?><button class="button">Review and submit deposit</button></form></section><?php elseif(!$methods): ?><section class="empty-state"><h2>No deposit methods available</h2><p>Please contact support for assistance.</p></section><?php endif; ?>
